import{_ as e,o,c as d,a2 as r}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Провайдеры и модели","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/providers/llm.md","filePath":"ru/integrations/providers/llm.md","lastUpdated":1792323081000}'),i={name:"ru/integrations/providers/llm.md"};function a(l,t,n,c,s,p){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="проваидеры-и-модели" tabindex="-1">Провайдеры и модели <a class="header-anchor" href="#проваидеры-и-модели" aria-label="Permalink to &quot;Провайдеры и модели&quot;">​</a></h1><p>Чтобы полноценно пользоваться Memoh, обычно нужно настроить:</p><ul><li>один или несколько <strong>провайдеров</strong>, определяющих, как Memoh обращается к вышестоящим API;</li><li>одну или несколько <strong>моделей</strong> под этими провайдерами;</li><li>опционально <strong>провайдеров речи</strong>, если нужен синтез речи из текста;</li><li>опционально <strong>провайдеров транскрипции</strong>, если нужно распознавание речи.</li></ul><p>Провайдеры и модели для чата и эмбеддингов управляются на странице <strong>Models</strong> приложения. Модели речи управляются на странице настроек <strong>Speech</strong>, а модели транскрипции — на странице настроек Transcription.</p><hr><h2 id="основы-проваидеров" tabindex="-1">Основы провайдеров <a class="header-anchor" href="#основы-проваидеров" aria-label="Permalink to &quot;Основы провайдеров&quot;">​</a></h2><p><strong>Провайдер</strong> хранит сведения о подключении к одному вышестоящему сервису, например:</p><ul><li>протокол API (<code>client_type</code>);</li><li>base URL, если протокол его требует;</li><li>учётные данные — API-ключ или OAuth-токен.</li></ul><p>Типичные примеры: OpenAI-совместимые конечные точки, Anthropic, Google Gemini, OpenAI Codex и GitHub Copilot.</p><h3 id="создание-проваидера" tabindex="-1">Создание провайдера <a class="header-anchor" href="#создание-проваидера" aria-label="Permalink to &quot;Создание провайдера&quot;">​</a></h3><p>Провайдеры создаются из <strong>каталога шаблонов</strong>. Каждый шаблон уже несёт правильный тип клиента, base URL и подобранный список моделей, так что обычно остаётся только ввести API-ключ.</p><ol><li>Откройте страницу <strong>Models</strong> в боковой панели настроек.</li><li>Нажмите <strong>Add Provider</strong> и выберите шаблон — список показывает только ещё не настроенные вами шаблоны и поддерживает поиск (в том числе по локализованным названиям вендоров).</li><li>Заполните учётные данные, которые запрашивает шаблон.</li><li>Сохраните. Провайдер и его предустановленные модели создаются при сохранении.</li></ol><p>В комплект входят шаблоны OpenAI, Anthropic, Google, OpenRouter, DeepSeek, <strong>Zhipu AI (bigmodel.cn)</strong>, Z.AI, Azure OpenAI, Cerebras, Cloudflare, Fireworks, Perplexity, Together и другие. Обратите внимание: <strong>Zhipu AI</strong> (<code>open.bigmodel.cn</code>, аккаунты материкового Китая) и <strong>Z.AI</strong> (<code>api.z.ai</code>, международные аккаунты) — это разные шаблоны с раздельными пространствами API-ключей; выбирайте тот, где был выдан ваш ключ.</p><p>Если ни один шаблон не подходит, по-прежнему можно создать полностью пользовательский провайдер.</p><p>Основные поля:</p><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Удобное отображаемое имя, например <code>OpenAI</code> или <code>Copilot</code>.</td></tr><tr><td><strong>Client Type</strong></td><td>Протокол API, который использует этот провайдер.</td></tr><tr><td><strong>Base URL</strong></td><td>Корневая конечная точка API, когда её требует выбранный тип клиента.</td></tr><tr><td><strong>API Key</strong></td><td>Аутентификация по токену, когда тип клиента использует прямые учётные данные.</td></tr></tbody></table><h3 id="типы-клиентов" tabindex="-1">Типы клиентов <a class="header-anchor" href="#типы-клиентов" aria-label="Permalink to &quot;Типы клиентов&quot;">​</a></h3><p>Сейчас Memoh поддерживает следующие типы клиентов:</p><table tabindex="0"><thead><tr><th>Client Type</th><th>Типичное применение</th></tr></thead><tbody><tr><td><code>openai-responses</code></td><td>Провайдеры в стиле OpenAI Responses API</td></tr><tr><td><code>openai-completions</code></td><td>Провайдеры, совместимые с OpenAI Chat Completions</td></tr><tr><td><code>anthropic-messages</code></td><td>Anthropic Messages API</td></tr><tr><td><code>google-generative-ai</code></td><td>Google Gemini API</td></tr><tr><td><code>openai-codex</code></td><td>OpenAI Codex / рабочий процесс кодинга на базе ChatGPT с OAuth</td></tr><tr><td><code>github-copilot</code></td><td>GitHub Copilot с device-OAuth</td></tr><tr><td><code>edge-speech</code></td><td>Тип провайдера речи для Microsoft Edge Read Aloud</td></tr><tr><td><code>openai-speech</code></td><td>OpenAI-совместимые провайдеры синтеза речи</td></tr><tr><td><code>openai-transcription</code></td><td>OpenAI-совместимые провайдеры распознавания речи</td></tr><tr><td><code>openrouter-speech</code></td><td>Провайдеры речи OpenRouter</td></tr><tr><td><code>openrouter-transcription</code></td><td>Провайдеры транскрипции OpenRouter</td></tr><tr><td><code>elevenlabs-speech</code></td><td>Провайдеры речи ElevenLabs</td></tr><tr><td><code>elevenlabs-transcription</code></td><td>Провайдеры транскрипции ElevenLabs</td></tr><tr><td><code>deepgram-speech</code></td><td>Провайдеры речи Deepgram</td></tr><tr><td><code>deepgram-transcription</code></td><td>Провайдеры транскрипции Deepgram</td></tr><tr><td><code>minimax-speech</code></td><td>Провайдеры речи MiniMax</td></tr><tr><td><code>volcengine-speech</code></td><td>Провайдеры речи Volcengine</td></tr><tr><td><code>alibabacloud-speech</code></td><td>Провайдеры речи Alibaba Cloud</td></tr><tr><td><code>microsoft-speech</code></td><td>Провайдеры речи Microsoft</td></tr><tr><td><code>google-transcription</code></td><td>Провайдеры транскрипции Google</td></tr></tbody></table><p>Типы клиентов для речи и транскрипции предназначены для аудиосценариев, а не для чата. Речь настраивается на странице настроек <strong>Speech</strong>, транскрипция — на странице настроек Transcription. Доступность конкретных моделей и голосов зависит от выбранного шаблона провайдера и вышестоящего аккаунта.</p><hr><h2 id="проваидеры-на-oauth" tabindex="-1">Провайдеры на OAuth <a class="header-anchor" href="#проваидеры-на-oauth" aria-label="Permalink to &quot;Провайдеры на OAuth&quot;">​</a></h2><p>Большинство типов провайдеров использует обычный API-ключ. Два заметных исключения — <code>openai-codex</code> и <code>github-copilot</code>. Оба аутентифицируются через <strong>авторизацию устройства</strong> по одному и тому же потоку, и ни у одного нет поля API-ключа:</p><ol><li>Сначала создайте и <strong>сохраните</strong> провайдер — авторизация доступна только из панели деталей уже сохранённого провайдера.</li><li>В разделе <strong>Account</strong> нажмите <strong>Connect</strong>. Memoh покажет URL для проверки и одноразовый код пользователя с обратным отсчётом срока действия.</li><li>Нажмите <strong>Copy &amp; Open</strong>, введите код на странице проверки провайдера — и Memoh завершит авторизацию автоматически.</li></ol><blockquote><p>Вводите код только на показанном URL для проверки — коды устройства могут использоваться для фишинга.</p></blockquote><p>После этого на провайдере отображается подключённый аккаунт, а <strong>Revoke</strong> отключает его.</p><h3 id="openai-codex" tabindex="-1">OpenAI Codex <a class="header-anchor" href="#openai-codex" aria-label="Permalink to &quot;OpenAI Codex&quot;">​</a></h3><ul><li>Использует тип клиента <code>openai-codex</code>; шаблон из комплекта указывает на <code>https://chatgpt.com/backend-api</code></li><li>Входит через ваш аккаунт ChatGPT</li></ul><p>Хороший выбор, когда нужен доступ к моделям в стиле Codex для задач, ориентированных на код.</p><h3 id="github-copilot" tabindex="-1">GitHub Copilot <a class="header-anchor" href="#github-copilot" aria-label="Permalink to &quot;GitHub Copilot&quot;">​</a></h3><ul><li>Использует тип клиента <code>github-copilot</code></li><li>Входит через ваш аккаунт GitHub</li></ul><p>GitHub Copilot особенно полезен, если у вас уже есть доступ к чат- и эмбеддинг-моделям на базе Copilot и вы хотите переиспользовать его из Memoh.</p><div class="warning custom-block"><p class="custom-block-title">Примечание при обновлении</p><p>Раньше учётные данные Copilot хранились для каждого пользователя отдельно. Теперь это единые учётные данные уровня провайдера, как у Codex. После обновления существующего развёртывания один раз переавторизуйте провайдер Copilot.</p></div><h3 id="управляемые-каталоги-моделеи" tabindex="-1">Управляемые каталоги моделей <a class="header-anchor" href="#управляемые-каталоги-моделеи" aria-label="Permalink to &quot;Управляемые каталоги моделей&quot;">​</a></h3><p>У обоих OAuth-провайдеров список моделей — это <strong>управляемый каталог</strong>, получаемый вживую от вышестоящего сервиса (у Codex статического списка моделей нет вовсе — он всегда отражает то, что доступно вашему аккаунту ChatGPT):</p><ul><li>Каталог синхронизируется автоматически после авторизации устройства, и его можно переимпортировать в любой момент.</li><li>Модели, исчезнувшие из вышестоящего каталога, помечаются недоступными, а не удаляются.</li><li>Переимпорт работает как upsert: новообнаруженные возможности дополняются, не перезаписывая вашу собственную конфигурацию моделей.</li></ul><hr><h2 id="импорт-моделеи" tabindex="-1">Импорт моделей <a class="header-anchor" href="#импорт-моделеи" aria-label="Permalink to &quot;Импорт моделей&quot;">​</a></h2><p>Создав провайдер, вы можете импортировать или добавлять модели под ним.</p><p>Типичный порядок:</p><ol><li>Выберите провайдер.</li><li>Нажмите <strong>Import Models</strong>, если провайдер умеет отдавать каталог моделей.</li><li>Отметьте модели, которые нужно сохранить в Memoh.</li></ol><p>Можно добавлять модели и вручную, если вы уже знаете ID модели у вышестоящего сервиса.</p><h3 id="включение-моделеи" tabindex="-1">Включение моделей <a class="header-anchor" href="#включение-моделеи" aria-label="Permalink to &quot;Включение моделей&quot;">​</a></h3><p>У каждой строки модели на странице провайдера есть <strong>переключатель включения</strong>. Выключенные модели остаются там видимыми, чтобы их можно было включить снова, но исчезают из всех списков выбора моделей (настройки Bot, чат, эмбеддинги и так далее).</p><p>Значения по умолчанию зависят от того, как модель появилась:</p><ul><li>Модели, добавленные <strong>вручную</strong>, сразу включены.</li><li>Модели, созданные <strong>массовым импортом</strong>, по умолчанию <strong>выключены</strong> — так импорт большого каталога не заполоняет все списки выбора; включайте только те, что действительно хотите использовать.</li></ul><hr><h2 id="типы-моделеи" tabindex="-1">Типы моделей <a class="header-anchor" href="#типы-моделеи" aria-label="Permalink to &quot;Типы моделей&quot;">​</a></h2><p>Memoh различает четыре типа моделей:</p><table tabindex="0"><thead><tr><th>Тип</th><th>Назначение</th></tr></thead><tbody><tr><td><code>chat</code></td><td>Основные LLM для разговора, вызова инструментов, рассуждений и генерации изображений</td></tr><tr><td><code>embedding</code></td><td>Векторные модели для памяти и поиска</td></tr><tr><td><code>speech</code></td><td>Модели синтеза речи, используемые TTS-провайдерами</td></tr><tr><td><code>transcription</code></td><td>Модели распознавания речи, используемые провайдерами транскрипции</td></tr></tbody></table><p>Важное разграничение:</p><ul><li>Страница <strong>Models</strong> — это в первую очередь место управления моделями <code>chat</code> и <code>embedding</code>.</li><li>Модели <code>speech</code> доступны через страницу настроек <strong>Speech</strong>.</li><li>Модели <code>transcription</code> доступны через страницу настроек Transcription.</li></ul><hr><h2 id="настроика-чат-модели" tabindex="-1">Настройка чат-модели <a class="header-anchor" href="#настроика-чат-модели" aria-label="Permalink to &quot;Настройка чат-модели&quot;">​</a></h2><p>При добавлении чат-модели важнее всего такие поля:</p><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Model ID</strong></td><td>Точный идентификатор у вышестоящего сервиса, например <code>gpt-4o</code> или <code>claude-sonnet-4.6</code>.</td></tr><tr><td><strong>Name</strong></td><td>Удобное отображаемое имя в интерфейсе.</td></tr><tr><td><strong>Description</strong></td><td>Необязательный текст; показывается подсказкой в списках моделей, по нему работает поиск в списках выбора.</td></tr><tr><td><strong>Compatibilities</strong></td><td>Флаги возможностей, такие как <code>vision</code>, <code>tool-call</code>, <code>image-output</code> и <code>reasoning</code>.</td></tr><tr><td><strong>Context Window</strong></td><td>Примерный максимальный бюджет контекста модели.</td></tr></tbody></table><h3 id="совместимости" tabindex="-1">Совместимости <a class="header-anchor" href="#совместимости" aria-label="Permalink to &quot;Совместимости&quot;">​</a></h3><p>По флагам совместимости Memoh решает, какие функции модель может безопасно обслуживать:</p><table tabindex="0"><thead><tr><th>Совместимость</th><th>Значение</th></tr></thead><tbody><tr><td><code>vision</code></td><td>Модель принимает изображения на вход</td></tr><tr><td><code>tool-call</code></td><td>Модель умеет вызывать инструменты</td></tr><tr><td><code>image-output</code></td><td>Модель умеет генерировать изображения</td></tr><tr><td><code>reasoning</code></td><td>Модель предоставляет явные режимы рассуждения / уровни усилий</td></tr></tbody></table><p>Если модель поддерживает рассуждения, она может также объявлять <code>reasoning_efforts</code>: <code>none</code>, <code>low</code>, <code>medium</code>, <code>high</code> или <code>xhigh</code>.</p><h3 id="context-window" tabindex="-1"><code>context_window</code> <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;`context_window`&quot;">​</a></h3><p><code>context_window</code> важен, потому что Memoh использует его, чтобы:</p><ul><li>вычислять использование контекста сессии в приложении;</li><li>формировать вывод <code>/status</code>;</li><li>определять, когда сессия приближается к лимиту промпта;</li><li>направлять <a href="./../../guides/compaction.html">сжатие контекста</a>.</li></ul><p>Если оставить <code>context_window</code> пустым, моделью всё равно можно пользоваться, но Memoh не сможет показать точный процент использования для неё.</p><h3 id="модели-генерации-изображении" tabindex="-1">Модели генерации изображений <a class="header-anchor" href="#модели-генерации-изображении" aria-label="Permalink to &quot;Модели генерации изображений&quot;">​</a></h3><p>Теперь Memoh позволяет назначить Bot отдельную модель <strong>Image Generation Model</strong>. Это должна быть чат-модель, среди совместимостей которой есть <code>image-output</code>.</p><p>Так генерацию изображений при необходимости можно держать отдельно от чат-модели по умолчанию.</p><hr><h2 id="модели-эмбеддингов" tabindex="-1">Модели эмбеддингов <a class="header-anchor" href="#модели-эмбеддингов" aria-label="Permalink to &quot;Модели эмбеддингов&quot;">​</a></h2><p>Модели эмбеддингов используются для семантической индексации и поиска.</p><p>Обязательное поле:</p><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Dimensions</strong></td><td>Размерность вектора на выходе эмбеддинга, например <code>1536</code>.</td></tr></tbody></table><p>Используйте модели эмбеддингов с провайдерами памяти и любыми функциями, которые опираются на векторный поиск.</p><hr><h2 id="модели-речи-и-транскрипции" tabindex="-1">Модели речи и транскрипции <a class="header-anchor" href="#модели-речи-и-транскрипции" aria-label="Permalink to &quot;Модели речи и транскрипции&quot;">​</a></h2><p>Модели речи управляются на странице настроек <strong>Speech</strong>, а не через стандартный поток чат-провайдеров.</p><p>Текущие категории провайдеров речи:</p><ul><li>Edge через <code>edge-speech</code></li><li>OpenAI-совместимые через <code>openai-speech</code></li><li>OpenRouter через <code>openrouter-speech</code></li><li>ElevenLabs через <code>elevenlabs-speech</code></li><li>Deepgram через <code>deepgram-speech</code></li><li>MiniMax через <code>minimax-speech</code></li><li>Volcengine через <code>volcengine-speech</code></li><li>Alibaba Cloud через <code>alibabacloud-speech</code></li><li>Microsoft через <code>microsoft-speech</code></li></ul><p>Модели транскрипции управляются на странице настроек Transcription. Текущие категории провайдеров транскрипции:</p><ul><li>OpenAI-совместимые через <code>openai-transcription</code></li><li>OpenRouter через <code>openrouter-transcription</code></li><li>ElevenLabs через <code>elevenlabs-transcription</code></li><li>Deepgram через <code>deepgram-transcription</code></li><li>Google через <code>google-transcription</code></li></ul><p>Это разделение важно, потому что у аудиомоделей есть зависящие от провайдера настройки голоса, формата, скорости, высоты тона, языка и распознавания, которые не применимы к моделям чата и эмбеддингов.</p><hr><h2 id="рекомендуемая-ментальная-модель" tabindex="-1">Рекомендуемая ментальная модель <a class="header-anchor" href="#рекомендуемая-ментальная-модель" aria-label="Permalink to &quot;Рекомендуемая ментальная модель&quot;">​</a></h2><p>Для большинства Bot думайте о параллельных ролях моделей:</p><ul><li><strong>Чат-модель</strong> — для обычных разговоров</li><li><strong>Модель эмбеддингов</strong> — для поиска по памяти</li><li><strong>Модели речи / транскрипции / изображений</strong> — для вспомогательных возможностей вроде синтеза речи, распознавания речи и генерации изображений</li></ul><p>Не нужно заставлять одну модель делать всё.</p><hr><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше&quot;">​</a></h2><ul><li>Как назначить Bot модели чата, изображений, памяти и синтеза речи — см. <a href="./../../guides/working-with-bots.html">Управление Bot</a>.</li><li>Провайдеры и модели речи настраиваются на странице настроек <strong>Speech</strong>.</li><li>Распознавание речи настраивается на странице настроек Transcription в приложении.</li></ul>',89)])])}const u=e(i,[["render",a]]);export{g as __pageData,u as default};
